<?php
declare(strict_types=1);

/**
 * Fault guides. Each: service, q (page heading), s (short label for the fault
 * finder), lead, causes [[name, text]], checks (safe things an owner can do),
 * stop (when to stop and call), fix (what we do), lcd (what the display shows).
 */
return [
    // ── Fridge ──────────────────────────────────────────────────
    'fridge-not-cooling' => ['service' => 'fridge-repairs', 'q' => 'Fridge not cooling? Here is what is usually wrong', 's' => 'Not cooling', 'lcd' => '28',
        'lead' => 'If the light works but the food is warm, the fridge has power and the fault is in the part that makes or moves the cold. These are the most common causes.',
        'causes' => [['Blocked airflow', 'In most no-frost fridges the cold is made in the freezer and blown into the fridge. Food packed against the vent, or ice behind the panel, stops it.'], ['Defrost fault', 'When the defrost heater, sensor or timer fails, the cooling coil becomes a block of ice. The freezer stays cold for a while and the fridge goes warm first.'], ['Fan not running', 'A dead evaporator fan leaves the cold trapped. A dead condenser fan lets the compressor overheat and cut out.'], ['Compressor or start relay', 'A compressor that hums for a few seconds, clicks and goes quiet often has a failed start relay. That is a far smaller job than a new compressor.'], ['Gas leak', 'If the compressor runs all day and nothing gets cold, the system may have lost its gas. The leak has to be found and closed before it is filled again.']],
        'checks' => ['Check that the dial or display was not bumped, and that demo or holiday mode is off.', 'Move food away from the vents at the back.', 'Feel the sides or the back: warm is normal, very hot means the fridge cannot get rid of heat. Give it space and brush dust off the coil.', 'Close a sheet of paper in the door. If it slides out easily, the seal is not holding.'],
        'stop' => 'If you smell burning, hear loud clicking every few minutes or the fridge trips the electricity, unplug it and leave it off.',
        'fix' => 'We test the fans, sensors, defrost heater, relay and compressor in that order, then check for a leak only if the pattern of frost points to one.'],
    'fridge-freezing-food' => ['service' => 'fridge-repairs', 'q' => 'Why is my fridge freezing the food?', 's' => 'Freezing food', 'lcd' => '-4',
        'lead' => 'Frozen lettuce and slushy milk mean the fridge keeps cooling when it should have stopped. Something is not telling it that the job is done.',
        'causes' => [['Faulty temperature sensor', 'If the sensor reads warmer than the truth, the fridge keeps running.'], ['Damper stuck open', 'The small flap between freezer and fridge lets freezing air through all the time.'], ['Thermostat worn', 'On a simple dial fridge the thermostat contacts can stick closed.'], ['Food in the air stream', 'Anything directly in front of the vent freezes first, even in a healthy fridge.']],
        'checks' => ['Set the fridge to the middle and wait a full day before judging.', 'Keep wet vegetables and bottles away from the back vent.', 'Put a glass of water on the middle shelf overnight and measure it in the morning; 3 to 5°C is right.'],
        'stop' => 'If the back wall is building up a sheet of ice, switch off and let it defrost with the door open. Do not scrape it.',
        'fix' => 'We measure the sensor against a real thermometer, test the damper and replace only the part that is lying.'],
    'fridge-leaking-water' => ['service' => 'fridge-repairs', 'q' => 'Fridge leaking water inside or on the floor', 's' => 'Leaking water', 'lcd' => 'LE',
        'lead' => 'Every fridge makes water when it defrosts. It should run down a small channel to a tray at the back and evaporate. A leak means the water took another way out.',
        'causes' => [['Blocked drain', 'Crumbs and ice plug the drain hole, so water backs up under the vegetable drawers.'], ['Door not sealing', 'Warm air leaks in and turns into more water than the tray can handle.'], ['Cracked drip tray', 'The tray under the fridge can crack when the fridge is moved.'], ['Water line to the dispenser', 'On plumbed fridges a loose fitting or a split pipe drips slowly.']],
        'checks' => ['Look for a small hole in the channel at the back wall and clear it gently with warm water.', 'Check that the fridge leans very slightly backwards, so the doors close on their own.', 'If it has a dispenser, close its water tap for a day. If the floor stays dry, the leak is in the line.'],
        'stop' => 'Water near the plug or the compressor is dangerous. Switch off at the wall and dry the floor before you touch the fridge.',
        'fix' => 'We clear and flush the drain, check the drain heater, seal and tray, and repair the water line if there is one.'],
    'freezer-ice-build-up' => ['service' => 'fridge-repairs', 'q' => 'Too much ice in the freezer', 's' => 'Ice build-up', 'lcd' => 'dEF',
        'lead' => 'A no-frost freezer should never grow ice. If it does, the part that melts the frost has stopped, or damp air is getting in.',
        'causes' => [['Defrost heater or sensor', 'The most common cause in no-frost fridges. The ice starts behind the back panel and grows outward.'], ['Door seal', 'A split or hardened seal pulls in humid air, and you see soft snow near the door.'], ['Door left open a crack', 'An overfull drawer or a frozen hinge is enough.'], ['Blocked drain', 'Melted water freezes again at the bottom, as a clear sheet.']],
        'checks' => ['Run a finger around the seal and look for splits.', 'Empty the freezer, switch off and let it thaw with the door open for a day. If the ice is back within a week or two, the defrost system has failed.', 'Never use a knife, hairdryer or boiling water.'],
        'stop' => 'If you hear a fan scraping the ice, switch the fridge off before the blade breaks.',
        'fix' => 'We thaw the coil properly, measure the heater, sensor and control, and replace the one that has failed.'],
    'fridge-noisy' => ['service' => 'fridge-repairs', 'q' => 'Noisy fridge: which sounds are normal and which are not', 's' => 'Strange noise', 'lcd' => 'HI',
        'lead' => 'Gurgling, a soft hum and the odd crack of plastic are normal. Grinding, rattling and repeated clicking are not.',
        'causes' => [['Fan hitting ice', 'A rhythmic scraping from the freezer.'], ['Worn fan bearing', 'A squeal or growl that changes when you open the door.'], ['Relay clicking', 'Click, hum, click every few minutes: the compressor is failing to start.'], ['Something touching', 'A pipe against the body, a loose tray or an uneven floor makes a buzz that stops when you press on it.']],
        'checks' => ['Open the freezer door. If the noise stops, it is the inside fan.', 'Make sure the fridge does not touch the wall or cupboard.', 'Level the feet.'],
        'stop' => 'Repeated clicking with no cooling wears the compressor out. Unplug it and call.',
        'fix' => 'We find the source with the panels off, then replace the fan, the relay or the mountings.'],
    'fridge-tripping-power' => ['service' => 'fridge-repairs', 'q' => 'Fridge trips the electricity', 's' => 'Trips the power', 'lcd' => 'OFF',
        'lead' => 'If the earth leakage drops when the fridge runs, current is escaping to the metal body. The time it happens tells us where.',
        'causes' => [['Defrost heater', 'Trips every eight to twelve hours, when the heater comes on.'], ['Compressor winding', 'Trips the moment the compressor starts.'], ['Damp in the wiring', 'Trips after a leak, a wash or a move.'], ['Ice maker or dispenser heater', 'Trips only when that part is in use.']],
        'checks' => ['Unplug the fridge and reset the board. If it holds, the fridge is the fault.', 'Plug it into another circuit once. If it trips there too, stop.', 'Note the time it trips and tell us.'],
        'stop' => 'Do not bypass the earth leakage or remove the earth wire. That switch is protecting your family.',
        'fix' => 'We test each part to earth with a meter, isolate the one that leaks and replace it.'],
    'fridge-ice-maker-dispenser' => ['service' => 'fridge-repairs', 'q' => 'Ice maker or water dispenser not working', 's' => 'Ice or water dispenser', 'lcd' => 'IcE',
        'lead' => 'Dispensers have their own pipes, valves, switches and heaters, so they can fail while the rest of the fridge is perfect.',
        'causes' => [['Water filter blocked', 'A filter past its date slows the flow to a trickle.'], ['Frozen water line', 'Common in side-by-sides when the freezer is set too cold.'], ['Inlet valve', 'No sound at all when you press the lever.'], ['Lever switch or lock', 'The panel may simply be locked, or the switch behind the lever is worn.']],
        'checks' => ['Check that the dispenser lock is off.', 'Check that the tap to the fridge is open.', 'Replace the filter if it is older than six months.'],
        'stop' => 'If water runs and does not stop, close the fridge water tap.',
        'fix' => 'We test the valve, switch, line heater and ice maker, and thaw or replace the line.'],

    // ── Washing machine ─────────────────────────────────────────
    'washing-machine-not-draining' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine not draining: causes and safe checks', 's' => 'Won\'t drain', 'lcd' => '5E',
        'lead' => 'A drum full of grey water and a locked door. The code is often 5E, 5C or OE. Start with the filter: often that is the whole story.',
        'causes' => [['Blocked pump filter', 'Coins, hair clips, baby socks and school badges collect here.'], ['Kinked or blocked hose', 'Pushing the machine back too far folds the hose flat.'], ['Failed drain pump', 'It hums without moving water, or makes no sound.'], ['Blocked house drain', 'If the pipe in the wall backs up, the machine is not to blame.'], ['Level sensor', 'The machine thinks it is empty, or full, when it is not.']],
        'checks' => ['Switch off at the wall. Put a shallow tray and towels in front of the filter flap.', 'Unscrew the filter slowly so the water comes out bit by bit, then clean it.', 'Straighten the hose and check that its end is not pushed too far down the drain.', 'Run the drain or spin programme.'],
        'stop' => 'If the water is hot, wait for it to cool before you open the filter.',
        'fix' => 'We test the pump, clear the sump and hose, and check the level sensor before closing the machine.'],
    'washing-machine-not-spinning' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine will not spin', 's' => 'Won\'t spin', 'lcd' => 'UE',
        'lead' => 'Clothes come out soaking. Machines refuse to spin for one of three reasons: the load, the water or the drive.',
        'causes' => [['Unbalanced load', 'One heavy blanket is worse than a full load. The machine tries, gives up and shows UE or Ub.'], ['Water still inside', 'It will not spin until it has drained.'], ['Worn suspension', 'Tired shock absorbers or rods let the drum swing, so the safety cuts the spin.'], ['Belt, brushes or motor', 'The drum turns slowly, or not at all, with a humming motor.'], ['Lid switch or door lock', 'Top loaders will not spin if the lid switch is broken.']],
        'checks' => ['Spread the load, or add a few towels to a single blanket.', 'Run a drain programme and listen for the pump.', 'Press down on the empty drum: it should rise and settle once, not bounce.'],
        'stop' => 'A bang at high speed can break the drum spider. Do not keep retrying.',
        'fix' => 'We check drain, suspension, belt, brushes and motor, then run a full spin test before we leave.'],
    'washing-machine-leaking' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine leaking on the floor', 's' => 'Leaking', 'lcd' => 'LE',
        'lead' => 'Where the water appears, and when, tells you most of what you need to know.',
        'causes' => [['Door seal', 'A front leak during the wash. Look for a tear or a hair clip in the fold.'], ['Soap drawer', 'Water in the first minutes, usually from too much foam or a blocked drawer.'], ['Inlet hose', 'A leak even when the machine is not running.'], ['Drain hose or pump', 'A leak only when it empties.'], ['Drum bearing seal', 'Rusty water from under the middle of the machine, with a roaring spin.']],
        'checks' => ['Dry the floor, run a short cycle and watch when the first drops appear.', 'Wipe the door seal and look into its folds.', 'Use less soap. High-foam powder in a front loader always ends on the floor.'],
        'stop' => 'Water under the machine and a plug on the floor do not mix. Switch off at the wall first.',
        'fix' => 'We trace the leak with the machine running, replace the seal, hose or pump, and re-test.'],
    'washing-machine-not-starting' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine dead or will not start', 's' => 'Won\'t start', 'lcd' => '----',
        'lead' => 'No lights at all is a power fault. Lights but no action is usually a door, water or control fault.',
        'causes' => [['Plug point or lead', 'The cheapest answer, and the first one to rule out.'], ['Door lock', 'The machine will not start until the lock reports back.'], ['Control board', 'Power cuts and surges damage the small power supply on the board.'], ['Child lock or delay', 'Not a fault, but it looks like one.']],
        'checks' => ['Test the plug point with a lamp or a charger.', 'Close the door firmly and listen for the click.', 'Cancel delay start and hold the child lock button for three seconds.', 'Unplug for ten minutes and try again.'],
        'stop' => 'If there is a burnt smell from the panel, do not plug it in again.',
        'fix' => 'We test the lead, the filter, the lock and the board with a meter. If the board is at fault we tell you whether it can be repaired.'],
    'washing-machine-shaking' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine shaking or walking across the floor', 's' => 'Shaking & banging', 'lcd' => 'Ub',
        'lead' => 'A machine that has just been delivered and one that is ten years old shake for very different reasons.',
        'causes' => [['Transport bolts', 'Still fitted on a new or recently moved front loader.'], ['Feet not level', 'One loose foot turns a spin into a dance.'], ['Shock absorbers or rods', 'Worn after years of heavy loads.'], ['Broken counterweight', 'The concrete block inside can crack or come loose.'], ['Drum bearing', 'A rumble that gets louder with speed.']],
        'checks' => ['Look at the back for bolts with plastic sleeves and remove them if the machine is new.', 'Rock the machine by its corners and adjust the feet until it is firm.', 'Wash mixed loads, not one heavy item.'],
        'stop' => 'Loud banging with metal sounds means something is loose inside. Stop the cycle.',
        'fix' => 'We check bolts, weights, springs, shock absorbers and bearings, and level the machine.'],
    'washing-machine-not-filling' => ['service' => 'washing-machine-repairs', 'q' => 'Washing machine not filling with water', 's' => 'Won\'t fill', 'lcd' => '4E',
        'lead' => 'The code is often 4E, 4C or IE. In areas with low water pressure it can also be the municipality and not the machine.',
        'causes' => [['Tap or pressure', 'After a water outage the tap may be half closed or the pressure low.'], ['Blocked inlet mesh', 'Sand in the pipes after repairs to the main collects in the small filter.'], ['Inlet valve', 'The coil has failed and the valve does not open.'], ['Door lock', 'No lock, no water.']],
        'checks' => ['Open the tap fully and check another tap in the house.', 'Close the tap, remove the hose and rinse the mesh with an old toothbrush.', 'Straighten the hose.'],
        'stop' => 'If it fills and does not stop, close the tap and switch off.',
        'fix' => 'We measure the pressure, the valve and the level sensor, and clear or replace the part.'],

    // ── Stove ───────────────────────────────────────────────────
    'stove-plate-not-working' => ['service' => 'stove-repairs', 'q' => 'Stove plate not working', 's' => 'Plate stays cold', 'lcd' => '0',
        'lead' => 'One dead plate on a working stove is usually a quick repair.',
        'causes' => [['Plate burnt out', 'The element inside has broken. It may have cracked or bulged.'], ['Switch worn', 'The plate works on some settings and not on others.'], ['Burnt connector', 'The wire under the plate has overheated. You may have smelled it.'], ['Indicator only', 'The light is out but the plate still heats.']],
        'checks' => ['Try every setting on the knob. Heat on some positions points to the switch or one part of the plate.', 'Look for cracks or a domed surface when the plate is cold.', 'Check whether other plates on the same side work.'],
        'stop' => 'Do not open the hob. Behind it is full mains power even when the knobs are off.',
        'fix' => 'We isolate the stove, measure the plate, the switch and the wiring, and replace the faulty part.'],
    'stove-tripping-power' => ['service' => 'stove-repairs', 'q' => 'Stove trips the electricity', 's' => 'Trips the power', 'lcd' => 'OFF',
        'lead' => 'Note which plate, or whether it is the oven. That one detail can halve the time it takes to find the fault.',
        'causes' => [['Moisture in a plate or element', 'Common after boiling over, or when the stove has not been used for a while.'], ['Element cracked', 'The inside touches the metal casing.'], ['Damaged wiring', 'Old insulation goes brittle above the oven.'], ['Overloaded circuit', 'If the breaker trips and not the earth leakage, too much may be running at once.']],
        'checks' => ['Switch everything on the stove off and reset the board. Then switch on one plate at a time.', 'See which switch trips: the earth leakage or the stove breaker.', 'Wipe up spills and let the plates dry.'],
        'stop' => 'If it trips with every knob off, switch the stove off at the wall and leave it off.',
        'fix' => 'We test each element to earth, check the wiring and connector block, and replace what is leaking.'],
    'stove-plate-stuck-on-high' => ['service' => 'stove-repairs', 'q' => 'Stove plate stuck on high', 's' => 'Stuck on full heat', 'lcd' => 'HI',
        'lead' => 'If the plate glows on every setting, the switch is no longer controlling it.',
        'causes' => [['Switch contacts welded', 'The contacts inside the energy regulator have stuck together.'], ['Wrong plate fitted', 'A replacement with the wrong wiring heats on every position.'], ['Damaged knob', 'The knob has cracked and no longer turns the shaft.']],
        'checks' => ['Pull the knob off and look at its plastic centre for cracks.', 'Compare with a working knob from another plate.'],
        'stop' => 'If the plate stays hot with the knob at zero, switch the stove off at the wall. Do not leave it unattended.',
        'fix' => 'We replace the switch, test every setting and check that the plate turns off fully.'],

    // ── Oven ────────────────────────────────────────────────────
    'oven-not-heating' => ['service' => 'oven-repairs', 'q' => 'Oven not heating up', 's' => 'Not heating', 'lcd' => '20',
        'lead' => 'If the plates work and the oven does not, the stove has power. The fault is in the oven\'s own circuit.',
        'causes' => [['Element burnt out', 'Look for a blister or a break in the bottom element.'], ['Thermostat failed', 'It never calls for heat.'], ['Selector switch', 'Grill works but bake does not, or the other way round.'], ['Timer set to automatic', 'On ovens with a clock, the oven waits for a time that never comes. Very common after a power cut.'], ['Safety cut-out', 'A thermal fuse has opened after overheating.']],
        'checks' => ['If there is a clock, set the time and switch it back to manual.', 'Try grill, bake and fan separately and note which ones heat.', 'Look at the elements when the oven is cold.'],
        'stop' => 'If there is a spark or a burning smell, switch off at the wall.',
        'fix' => 'We test the elements, the thermostat, the selector and the cut-out, and replace the failed one.'],
    'oven-uneven-baking' => ['service' => 'oven-repairs', 'q' => 'Oven burns one side or bakes unevenly', 's' => 'Uneven or too hot', 'lcd' => '230',
        'lead' => 'Cakes that burn at the back and stay raw in front usually point to a fan, a seal or a thermostat that has drifted.',
