        'checks' => ['Listen for the fan on the fan setting.', 'Put an oven thermometer on the middle shelf for half an hour at 180.', 'Run your hand around the closed door, without touching it, and feel for hot air.'],
        'stop' => 'An oven that keeps getting hotter must be switched off at the wall.',
        'fix' => 'We measure the real temperature, then replace the thermostat, the fan motor, the element or the seal.'],
    'oven-door-not-closing' => ['service' => 'oven-repairs', 'q' => 'Oven door will not close properly', 's' => 'Door won\'t close', 'lcd' => 'dOr',
        'lead' => 'A door that hangs open costs electricity, cooks the knobs and makes baking a guess.',
        'causes' => [['Hinge spring broken', 'The door drops or will not stay up.'], ['Seal loose or hard', 'The seal has slipped out of its clips or gone flat.'], ['Rack or tray in the way', 'A tray pushed in crooked holds the door open.'], ['Hinge bent', 'Usually from standing or leaning on the open door.']],
        'checks' => ['Take the racks out and try again.', 'Check that the seal is clipped in all the way round.', 'Look at the gap: the same on both sides means the seal, different means a hinge.'],
