    // ── Microwave ───────────────────────────────────────────────
    'microwave-not-heating' => ['service' => 'microwave-repairs', 'q' => 'Microwave runs but does not heat', 's' => 'Not heating', 'lcd' => '0:00',
        'lead' => 'If the light, plate and fan work but the food stays cold, the microwave has power and the part that makes the heat is not doing its job.',
        'causes' => [['High-voltage diode or fuse', 'A common reason for no heat after a power surge.'], ['Magnetron', 'The part that makes the heat. It wears out, and it fails early if the microwave is run empty.'], ['Door switch', 'If one of the safety switches behind the door does not close, the heat stays off.'], ['Low power setting', 'Defrost or a low power level warms food very slowly.']],
        'checks' => ['Check that it is not on defrost or a low power level.', 'Heat a cup of water on full power for one minute. If it is still cold, stop using it.', 'Open and close the door firmly and look for a bent latch.'],
