    'microwave-plate-not-turning' => ['service' => 'microwave-repairs', 'q' => 'Microwave plate not turning', 's' => 'Plate does not turn', 'lcd' => '0:30',
        'lead' => 'Food that is boiling on one side and cold on the other usually means the plate has stopped.',
        'causes' => [['Plate not seated', 'The glass plate must sit on the coupler in the middle.'], ['Roller ring dirty or broken', 'Dry food under the wheels stops them.'], ['Coupler worn', 'The small plastic piece in the middle slips.'], ['Turntable motor', 'The motor under the oven floor has failed.']],
        'checks' => ['Take out the plate and the roller ring, wash them and wipe the floor of the oven.', 'Put the ring back, then the plate, and turn it by hand until it drops into place.', 'Check that the dish is not touching the walls.'],
        'stop' => 'If it grinds or smells hot, stop using it.',
