    // ── Geyser ──────────────────────────────────────────────────
    'no-hot-water' => ['service' => 'geyser-repairs', 'q' => 'No hot water: what to check first', 's' => 'No hot water', 'lcd' => '15',
        'lead' => 'Cold showers have a short list of causes. Start at the distribution board.',
        'causes' => [['Breaker or isolator off', 'Tripped by a surge or switched off and forgotten.'], ['Thermostat failed', 'It no longer switches the element on.'], ['Element burnt out', 'The geyser has power but makes no heat.'], ['Timer or smart switch', 'Its clock is wrong after a power cut.'], ['Burnt connection', 'A loose wire at the thermostat or isolator.']],
        'checks' => ['Look for the geyser breaker and the isolator near the geyser.', 'If it trips again as soon as you switch it on, leave it off.', 'Check any timer clock.', 'Give it at least two hours after the power returns.'],
        'stop' => 'Do not remove the thermostat cover. It is live even when the water is cold.',
        'fix' => 'We isolate the supply, test the thermostat, the element and the wiring, and replace the failed part.'],
    'geyser-tripping' => ['service' => 'geyser-repairs', 'q' => 'Geyser keeps tripping the board', 's' => 'Trips the board', 'lcd' => 'OFF',
        'lead' => 'If the earth leakage holds with the geyser off and drops when you switch it on, the geyser is the first suspect.',
        'causes' => [['Element leaking to earth', 'The element has cracked and water has reached the wire. This is the usual cause.'], ['Water on the thermostat', 'A leaking gasket drips onto the terminals.'], ['Damaged cable', 'Heat or rodents in the roof.']],
        'checks' => ['Switch the geyser breaker off and reset the earth leakage.', 'Do not keep resetting it to squeeze out one more hot bath.'],
        'stop' => 'A tripping geyser means electricity and water are meeting. Keep it off until it has been tested.',
        'fix' => 'We test the element to earth, check for leaks at the gasket and replace the element, gasket or thermostat.'],
    'geyser-overflow-dripping' => ['service' => 'geyser-repairs', 'q' => 'Geyser overflow pipe dripping all day', 's' => 'Overflow dripping', 'lcd' => 'drP',
        'lead' => 'A little water while the geyser heats is normal, because water expands. All day is not.',
        'causes' => [['Pressure control valve', 'A worn or dirty valve lets water through all the time.'], ['Safety valve', 'It opens when the pressure or temperature is too high.'], ['Thermostat not switching off', 'The water overheats and the safety valve opens.'], ['High municipal pressure', 'Often worse at night.']],
        'checks' => ['Feel the water carefully: cold points to pressure, hot points to temperature.', 'Check whether it stops when the geyser is off for an hour.', 'Put a bucket under the pipe and measure an hour of drips.'],
        'stop' => 'Very hot water or steam from the overflow: switch the geyser off at the board at once.',
